export const DICTIONARIES = {
  en: Object.fromEntries(PHRASES.map(([tr, en]) => [tr, en])),
  ar: Object.fromEntries(PHRASES.map(([tr, , ar]) => [tr, ar])),
};

export function translate(lang, text, vars) {
  const table = DICTIONARIES[lang];
  let output = (table && table[text]) || text;
  if (vars) output = output.replace(/\{(\w+)\}/g, (match, key) => (vars[key] === undefined ? match : String(vars[key])));
  return output;
}

